M = Mod('m03', 13, dict(cmp=('Comparators and hysteresis', 'Mạch so sánh và trễ (hysteresis)'), sum=('Summing, averaging, scaling amplifiers', 'Mạch cộng, trung bình, cộng có trọng số'),
                        intg=('Integrator', 'Mạch tích phân'), dif=('Differentiator', 'Mạch vi phân'), ts=('Troubleshooting', 'Tìm lỗi')))
mcq = M.mcq
mcq(1,710,'In a zero-level detector, the output changes state when the input','Ở mạch phát hiện mức không (zero-level detector), ngõ ra đổi trạng thái khi ngõ vào',[('is positive','dương'),('is negative','âm'),('crosses zero','đi qua mức không'),('has a zero rate of change','có tốc độ biến thiên bằng không')],2,'The comparator output flips each time Vin crosses the 0 V reference, in either direction.','Ngõ ra của mạch so sánh lật mỗi lần Vin cắt mức tham chiếu 0 V, theo cả hai chiều.','cmp')
mcq(2,710,'The zero-level detector is one application of a','Mạch phát hiện mức không là một ứng dụng của',[('comparator','mạch so sánh'),('differentiator','mạch vi phân'),('summing amplifier','mạch cộng'),('diode','điốt')],0,'It is a comparator whose reference voltage is 0 V.','Đó là mạch so sánh có điện áp tham chiếu bằng 0 V.','cmp')
mcq(3,710,'Noise on the input of a comparator can cause the output to','Nhiễu ở ngõ vào mạch so sánh có thể làm ngõ ra',[('hang up in one state','kẹt ở một trạng thái'),('go to zero','về không'),('change back and forth erratically between two states','chuyển qua lại thất thường giữa hai trạng thái'),('produce the amplified noise signal','tạo ra tín hiệu nhiễu được khuếch đại')],2,'Near the trigger level noise repeatedly pushes the input across the reference, so the output chatters between the two saturated levels.','Gần ngưỡng, nhiễu liên tục đẩy ngõ vào qua mức tham chiếu nên ngõ ra “rung” giữa hai mức bão hòa.','cmp')
mcq(4,710,'The effects of noise can be reduced by','Ảnh hưởng của nhiễu có thể giảm bằng cách',[('lowering the supply voltage','hạ điện áp nguồn'),('using positive feedback','dùng hồi tiếp dương'),('using negative feedback','dùng hồi tiếp âm'),('using hysteresis','dùng hysteresis'),('answers (b) and (d)','đáp án (b) và (d)')],4,'Hysteresis is created by positive feedback; the two trigger points make the output ignore noise smaller than the hysteresis voltage.','Hysteresis được tạo bằng hồi tiếp dương; hai ngưỡng khiến ngõ ra bỏ qua nhiễu nhỏ hơn điện áp hysteresis.','cmp',2,True)
mcq(5,710,'A comparator with hysteresis','Mạch so sánh có hysteresis',[('has one trigger point','có một ngưỡng chuyển'),('has two trigger points','có hai ngưỡng chuyển'),('has a variable trigger point','có ngưỡng chuyển thay đổi được'),('is like a magnetic circuit','giống một mạch từ')],1,'The upper (VUTP) and lower (VLTP) trigger points differ by VHYS.','Ngưỡng trên (VUTP) và ngưỡng dưới (VLTP) cách nhau VHYS.','cmp')
mcq(6,710,'In a comparator with hysteresis,','Ở mạch so sánh có hysteresis,',[('a bias voltage is applied between the two inputs','đặt một điện áp phân cực giữa hai ngõ vào'),('only one supply voltage is used','chỉ dùng một nguồn cấp'),('a portion of the output is fed back to the inverting input','một phần ngõ ra được đưa về ngõ vào đảo'),('a portion of the output is fed back to the noninverting input','một phần ngõ ra được đưa về ngõ vào không đảo')],3,'Feeding part of the output back to the (+) input is positive feedback and gives the two trigger points.','Đưa một phần ngõ ra về ngõ (+) là hồi tiếp dương và tạo ra hai ngưỡng chuyển.','cmp')
mcq(7,710,'Using output bounding in a comparator','Việc giới hạn (bounding) ngõ ra của mạch so sánh',[('makes it faster','làm nó nhanh hơn'),('keeps the output positive','giữ ngõ ra luôn dương'),('limits the output levels','giới hạn các mức ngõ ra'),('stabilizes the output','làm ổn định ngõ ra')],2,'Zener diodes clamp the output to ±(VZ + 0.7 V) instead of the saturation levels.','Các điốt zener kẹp ngõ ra ở ±(VZ + 0,7 V) thay vì mức bão hòa.','cmp')
mcq(8,710,'A summing amplifier can have','Mạch cộng có thể có',[('only one input','chỉ một ngõ vào'),('only two inputs','chỉ hai ngõ vào'),('any number of inputs','số ngõ vào bất kỳ')],2,'Each added input resistor adds one more current into the summing node.','Mỗi điện trở vào thêm một dòng vào nút cộng.','sum')
mcq(9,711,'If the voltage gain for each input of a summing amplifier with a 4.7 kΩ feedback resistor is unity, the input resistors must have a value of','Nếu độ lợi của mỗi ngõ vào mạch cộng có Rf = 4,7 kΩ bằng 1 thì các điện trở vào phải có giá trị',[('4.7 kΩ','4,7 kΩ'),('4.7 kΩ divided by the number of inputs','4,7 kΩ chia cho số ngõ vào'),('4.7 kΩ times the number of inputs','4,7 kΩ nhân với số ngõ vào')],0,'Gain per input = Rf/Ri = 1 → Ri = Rf = 4.7 kΩ, whatever the number of inputs.','Độ lợi mỗi ngõ = Rf/Ri = 1 → Ri = Rf = 4,7 kΩ, bất kể số ngõ vào.','sum')
mcq(10,711,'An averaging amplifier has five inputs. The ratio Rf/Ri must be','Mạch trung bình có năm ngõ vào. Tỉ số Rf/Ri phải bằng',[('5','5'),('0.2','0,2'),('1','1')],1,'Averaging needs gain 1/n per input: Rf/Ri = 1/5 = 0.2.','Lấy trung bình cần độ lợi 1/n mỗi ngõ: Rf/Ri = 1/5 = 0,2.','sum')
mcq(12,711,'In an ideal integrator, the feedback element is a','Trong mạch tích phân lý tưởng, phần tử hồi tiếp là',[('resistor','điện trở'),('capacitor','tụ điện'),('zener diode','điốt zener'),('voltage divider','bộ chia áp')],1,'The capacitor in the feedback path integrates the input current Vin/Ri.','Tụ trong nhánh hồi tiếp tích phân dòng vào Vin/Ri.','intg')
mcq(13,711,'For a step input, the output of an integrator is','Với tín hiệu vào là bước nhảy, ngõ ra của mạch tích phân là',[('a pulse','một xung'),('a triangular waveform','sóng tam giác'),('a spike','một xung nhọn'),('a ramp','một đường dốc (ramp)')],3,'A constant input current charges C linearly, so the output is a ramp.','Dòng vào không đổi nạp tụ tuyến tính nên ngõ ra là đường dốc.','intg')
mcq(14,711,'The rate of change of an integrator’s output voltage in response to a step input is set by','Tốc độ biến thiên điện áp ngõ ra mạch tích phân khi vào là bước nhảy được quyết định bởi',[('the RC time constant','hằng số thời gian RC'),('the amplitude of the step input','biên độ của bước nhảy'),('the current through the capacitor','dòng qua tụ'),('all of these','tất cả các yếu tố trên')],3,'ΔVout/Δt = −Vin/(Ri·C): it depends on Vin, on the RC product and equals IC/C.','ΔVout/Δt = −Vin/(Ri·C): phụ thuộc Vin, tích RC và bằng IC/C.','intg',2)
mcq(15,711,'In a differentiator, the feedback element is a','Trong mạch vi phân, phần tử hồi tiếp là',[('resistor','điện trở'),('capacitor','tụ điện'),('zener diode','điốt zener'),('voltage divider','bộ chia áp')],0,'Rf sits in the feedback path and the capacitor is in series with the input.','Rf nằm ở nhánh hồi tiếp còn tụ nối tiếp với ngõ vào.','dif')
mcq(16,711,'The output of a differentiator is proportional to','Ngõ ra của mạch vi phân tỉ lệ với',[('the RC time constant','hằng số thời gian RC'),('the rate at which the input is changing','tốc độ biến thiên của tín hiệu vào'),('the amplitude of the input','biên độ tín hiệu vào'),('answers (a) and (b)','đáp án (a) và (b)')],3,'Vout = −Rf·C·(dVin/dt): proportional to RC and to the input’s rate of change.','Vout = −Rf·C·(dVin/dt): tỉ lệ với RC và với tốc độ biến thiên của ngõ vào.','dif',2,True)
mcq(17,711,'When you apply a triangular waveform to the input of a differentiator, the output is','Khi đưa sóng tam giác vào mạch vi phân, ngõ ra là',[('a dc level','mức một chiều'),('an inverted triangular waveform','sóng tam giác đảo'),('a square waveform','sóng vuông'),('the first harmonic of the triangular waveform','sóng hài bậc một của tam giác')],2,'A triangle has constant positive then negative slope, so the derivative is a square wave.','Sóng tam giác có độ dốc dương rồi âm không đổi nên đạo hàm là sóng vuông.','dif')
