tf(5,709,'A summing amplifier can have more than two inputs.','Mạch cộng có thể có nhiều hơn hai ngõ vào.',1,'Any number of input resistors may be added.','Có thể thêm số lượng điện trở vào tùy ý.','sum')
tf(6,709,'The gain of a summing amplifier must always be unity (1).','Độ lợi của mạch cộng luôn phải bằng 1.',0,'Rf/Ri can be chosen for gain >1 (adder with gain), <1 (averager) or per-input weights (scaling adder).','Rf/Ri có thể chọn để có độ lợi >1, <1 (trung bình) hoặc theo trọng số từng ngõ.','sum')
tf(7,709,'DAC stands for digital-to-analog comparator.','DAC là viết tắt của “digital-to-analog comparator”.',0,'DAC = digital-to-analog converter.','DAC = digital-to-analog converter (bộ chuyển đổi số–tương tự).','sum')
tf(8,709,'An R/2R ladder circuit is one form of DAC.','Mạch thang R/2R là một dạng DAC.',1,'Binary-weighted and R/2R ladder are the two common DAC forms.','Mạch trọng số nhị phân và mạch thang R/2R là hai dạng DAC phổ biến.','sum')
tf(9,709,'An integrator produces a ramp when a step input is applied.','Mạch tích phân tạo đường dốc khi vào là bước nhảy.',1,'ΔVout/Δt = −Vin/(Ri·C) is constant.','ΔVout/Δt = −Vin/(Ri·C) là hằng số.','intg')
tf(10,709,'In a practical integrator, a resistor is connected across the capacitor.','Trong mạch tích phân thực tế, một điện trở được mắc song song với tụ.',1,'Floyd: a resistor in parallel with the feedback capacitor prevents saturation caused by offset errors.','Floyd: điện trở song song với tụ hồi tiếp ngăn bão hòa do sai số offset.','intg')
tf(11,709,'When a triangular waveform is applied to a differentiator, a sine wave appears on the output.','Khi đưa sóng tam giác vào mạch vi phân thì ngõ ra là sóng sin.',0,'The output is a square wave.','Ngõ ra là sóng vuông.','dif')
tf(12,709,'In a practical differentiator, a resistor is connected in series with the capacitor.','Trong mạch vi phân thực tế, một điện trở được mắc nối tiếp với tụ.',1,'Floyd: Rin in series with C forms a low-pass filter that limits the high-frequency gain and noise.','Floyd: Rin nối tiếp C tạo bộ lọc thông thấp, hạn chế độ lợi và nhiễu ở tần số cao.','dif')
ca = M.ca
ca(2,709,'In the trigger circuit of Figure 13–9, if R1 is decreased to 50 kΩ, the upper trigger-point voltage will','Trong mạch ở Hình 13–9, nếu giảm R1 xuống 50 kΩ thì điện áp ngưỡng trên sẽ','assets/figs/m03/fig13_09.png',0,'VUTP = R2/(R1+R2)·Vout(max): R2/(R1+R2) rises from 100/200 = 0.5 to 100/150 = 0.667.','VUTP = R2/(R1+R2)·Vout(max): R2/(R1+R2) tăng từ 100/200 = 0,5 lên 100/150 = 0,667.','cmp')
ca(3,710,'If the zener diodes in Figure 13–13 are changed to ones with a rating of 5.6 V, the output voltage amplitude will','Nếu đổi các điốt zener ở Hình 13–13 sang loại 5,6 V thì biên độ điện áp ra sẽ','assets/figs/m03/fig13_13.png',0,'Bounded output = ±(VZ + 0.7 V): from ±5.4 V (4.7 V zeners) to ±6.3 V.','Ngõ ra bị giới hạn ở ±(VZ + 0,7 V): từ ±5,4 V (zener 4,7 V) lên ±6,3 V.','cmp')
ca(6,710,'If VIN1 is increased to 0.4 V and VIN2 is reduced to 0.3 V in Figure 13–23, the output voltage will','Nếu tăng VIN1 lên 0,4 V và giảm VIN2 xuống 0,3 V trong Hình 13–23 thì điện áp ra sẽ','assets/figs/m03/fig13_23.png',2,'With R1 = R2 = 1 kΩ and Rf = 10 kΩ, VOUT = −10(VIN1 + VIN2) = −7 V before (0.2 + 0.5) and after (0.4 + 0.3): unchanged.','Với R1 = R2 = 1 kΩ và Rf = 10 kΩ, VOUT = −10(VIN1 + VIN2) = −7 V trước (0,2 + 0,5) và sau (0,4 + 0,3): không đổi.','sum')
ca(9,710,'If the value of C in Figure 13–35 is reduced, the frequency of the output waveform will','Nếu giảm giá trị C trong Hình 13–35 thì tần số của dạng sóng ra sẽ','assets/figs/m03/fig13_35.png',2,'The integrator output follows the input period (400 μs); a smaller C only makes the ramp steeper (larger amplitude), not faster.','Ngõ ra của mạch tích phân theo chu kỳ ngõ vào (400 μs); C nhỏ hơn chỉ làm dốc hơn (biên độ lớn hơn) chứ không đổi tần số.','intg')
ca(10,710,'If the frequency of the input waveform in Figure 13–40 is increased, the amplitude of the output voltage will','Nếu tăng tần số của tín hiệu vào trong Hình 13–40 thì biên độ điện áp ra sẽ','assets/figs/m03/fig13_40.png',0,'|Vout| = Rf·C·|dVin/dt|; at the same peak value a higher frequency means steeper slopes, so a larger output.','|Vout| = Rf·C·|dVin/dt|; cùng giá trị đỉnh, tần số cao hơn thì độ dốc lớn hơn nên ngõ ra lớn hơn.','dif')
ess = M.ess; mu = lambda x: f'{x:.4g}'
ess(1,711,'An op-amp has Aol = 80,000 and saturation levels ±12 V on ±15 V supplies. A differential input of 0.15 mV rms is applied. What is the peak-to-peak output?','Op-amp có Aol = 80.000, mức bão hòa ±12 V với nguồn ±15 V. Đặt tín hiệu vi sai 0,15 mV rms. Điện áp ra đỉnh–đỉnh là bao nhiêu?',
    f'Unlimited output = 80,000 × 0.15 mV = {80000*0.15e-3:.0f} V rms → {80000*0.15e-3*math.sqrt(2):.1f} V peak, far beyond ±12 V, so the output clips: 24 V peak-to-peak with distortion (book: 24 V, with distortion).',f'Ngõ ra không giới hạn = 80.000 × 0,15 mV = {80000*0.15e-3:.0f} V rms → {80000*0.15e-3*math.sqrt(2):.1f} V đỉnh, vượt xa ±12 V nên bị xén: 24 V đỉnh–đỉnh, méo (sách: 24 V, có méo).','cmp',1,True)
r1, r2 = 47, 18; ut = r2 / (r1 + r2) * 10
ess(3,712,'Figure 13–61: R1 = 47 kΩ, R2 = 18 kΩ, Vout(max) = ±10 V. Calculate VUTP and VLTP.','Hình 13–61: R1 = 47 kΩ, R2 = 18 kΩ, Vout(max) = ±10 V. Tính VUTP và VLTP.',
    f'VUTP = R2/(R1+R2)·(+10 V) = 18/65 × 10 = {ut:.2f} V; VLTP = −{ut:.2f} V (book: ±2.77 V).',f'VUTP = R2/(R1+R2)·(+10 V) = 18/65 × 10 = {ut:.2f} V; VLTP = −{ut:.2f} V (sách: ±2,77 V).','cmp',2,True)
ess(4,712,'What is the hysteresis voltage in Figure 13–61?','Điện áp hysteresis ở Hình 13–61 là bao nhiêu?',f'VHYS = VUTP − VLTP = {ut:.2f} − (−{ut:.2f}) = {2*ut:.2f} V.',f'VHYS = VUTP − VLTP = {ut:.2f} − (−{ut:.2f}) = {2*ut:.2f} V.','cmp',1)
ua = 18 / 51 * 11; ub = 68 / 218 * 11
ess(6,712,'Hysteresis voltage of each comparator in Figure 13–63 (Vout(max) = ±11 V): (a) R1 = 33 kΩ, R2 = 18 kΩ; (b) R1 = 150 kΩ, R2 = 68 kΩ.','Điện áp hysteresis của mỗi mạch ở Hình 13–63 (Vout(max) = ±11 V): (a) R1 = 33 kΩ, R2 = 18 kΩ; (b) R1 = 150 kΩ, R2 = 68 kΩ.',
    f'(a) VUTP = 18/51 × 11 = {ua:.2f} V → VHYS = 2·{ua:.2f} = {2*ua:.2f} V. (b) VUTP = 68/218 × 11 = {ub:.2f} V → VHYS = {2*ub:.2f} V.',f'(a) VUTP = 18/51 × 11 = {ua:.2f} V → VHYS = 2·{ua:.2f} = {2*ua:.2f} V. (b) VUTP = 68/218 × 11 = {ub:.2f} V → VHYS = {2*ub:.2f} V.','cmp')
k = 18 / 65; vp = 6.2 / (1 - k); vn = -0.7 / (1 - k)                                  # Fig 13-61: V(+) = k·Vout
kv, vnv, vpv = f'{k:.3f}'.replace('.', ','), f'{vn:.3f}'.replace('.', ',').replace('-', '−'), f'{vp:.2f}'.replace('.', ',')
ess(7,712,'A 6.2 V zener is connected from the output to the inverting input in Figure 13–61 with its cathode at the output. What are the positive and negative output levels? (Assume 0.7 V forward drop.)','Một zener 6,2 V nối từ ngõ ra về ngõ vào đảo ở Hình 13–61, catốt ở ngõ ra. Các mức ra dương và âm là bao nhiêu? (Giả sử sụt áp thuận 0,7 V.)',
    f'The zener feeds the output back to the inverting input, so once it conducts the op-amp holds V(−) ≈ V(+). In Figure 13–61 V(+) = Vout·R2/(R1 + R2) = Vout·18/65 = {k:.3f}·Vout (R1 = 47 kΩ, R2 = 18 kΩ). '
    f'Positive: the zener is in breakdown, Vout = V(−) + 6.2 V = {k:.3f}·Vout + 6.2 V, so Vout = 6.2/(1 − {k:.3f}) = {vp:.2f} V. Negative: the zener is forward biased, Vout = V(−) − 0.7 V, so Vout = −0.7/(1 − {k:.3f}) = {str(round(vn, 3)).replace('-', '−')} V (book: 8.57 V and −0.968 V). '
    'This is not the ±(VZ + 0.7 V) of a bounded inverting amplifier, because here the inverting input is not at ground.',
    f'Zener đưa ngõ ra về ngõ vào đảo, nên khi nó dẫn op-amp giữ V(−) ≈ V(+). Ở Hình 13–61, V(+) = Vout·R2/(R1 + R2) = Vout·18/65 = {kv}·Vout (R1 = 47 kΩ, R2 = 18 kΩ). '
    f'Mức dương: zener đánh thủng, Vout = V(−) + 6,2 V = {kv}·Vout + 6,2 V, nên Vout = 6,2/(1 − {kv}) = {vpv} V. Mức âm: zener dẫn thuận, Vout = V(−) − 0,7 V, nên Vout = −0,7/(1 − {kv}) = {vnv} V (sách: 8,57 V và −0,968 V). '
    'Đây không phải ±(VZ + 0,7 V) của mạch khuếch đại đảo có giới hạn, vì ở đây ngõ vào đảo không nối đất.', 'cmp')
ess(9,713,'Output voltage of each summing circuit in Figure 13–65: (a) inputs +1 V and +1.5 V, all resistors 10 kΩ; (b) inputs 0.1 V, 1 V, 0.5 V with Ri = 10 kΩ and Rf = 22 kΩ.','Điện áp ra của mỗi mạch cộng ở Hình 13–65: (a) vào +1 V và +1,5 V, mọi điện trở 10 kΩ; (b) vào 0,1 V, 1 V, 0,5 V với Ri = 10 kΩ và Rf = 22 kΩ.',
    f'(a) Rf/Ri = 1 → VOUT = −(1 + 1.5) = −2.5 V. (b) Rf/Ri = 2.2 → VOUT = −2.2(0.1 + 1 + 0.5) = −{2.2*1.6:.2f} V.',f'(a) Rf/Ri = 1 → VOUT = −(1 + 1,5) = −2,5 V. (b) Rf/Ri = 2,2 → VOUT = −2,2(0,1 + 1 + 0,5) = −{2.2*1.6:.2f} V.','sum')
ess(10,713,'Figure 13–66: R1 = R2 = Rf = 22 kΩ, VIN1 = +1 V, VIN2 = +1.8 V. Find (a) VR1 and VR2, (b) the current through Rf, (c) VOUT.','Hình 13–66: R1 = R2 = Rf = 22 kΩ, VIN1 = +1 V, VIN2 = +1,8 V. Tìm (a) VR1 và VR2, (b) dòng qua Rf, (c) VOUT.',
    f'(a) The inverting input is a virtual ground, so VR1 = 1 V and VR2 = 1.8 V. (b) If = 1/22k + 1.8/22k = {2.8/22*1e3:.1f} μA. (c) VOUT = −If·Rf = −{2.8:.1f} V.',f'(a) Ngõ vào đảo là đất ảo nên VR1 = 1 V và VR2 = 1,8 V. (b) If = 1/22k + 1,8/22k = {2.8/22*1e3:.1f} μA. (c) VOUT = −If·Rf = −{2.8:.1f} V.','sum')
ess(11,713,'Find Rf in Figure 13–66 so that the output is five times the sum of the inputs.','Tìm Rf ở Hình 13–66 để ngõ ra bằng năm lần tổng các ngõ vào.','Rf/Ri = 5 → Rf = 5 × 22 kΩ = 110 kΩ.','Rf/Ri = 5 → Rf = 5 × 22 kΩ = 110 kΩ.','sum',1)
ess(12,713,'Show a summing amplifier that averages eight input voltages. Use input resistances of 10 kΩ each.','Vẽ mạch cộng lấy trung bình tám điện áp vào. Dùng điện trở vào 10 kΩ mỗi cái.','Eight 10 kΩ input resistors to the inverting node and Rf/Ri = 1/8 → Rf = 10 kΩ / 8 = 1.25 kΩ; VOUT = −(V1 + … + V8)/8 (use an inverter if a positive average is wanted).','Tám điện trở vào 10 kΩ nối tới nút đảo và Rf/Ri = 1/8 → Rf = 10 kΩ/8 = 1,25 kΩ; VOUT = −(V1 + … + V8)/8 (dùng thêm mạch đảo nếu cần giá trị trung bình dương).','sum',1)
v13 = 10 / 10 * 2 + 10 / 33 * 3 + 10 / 91 * 3 + 10 / 180 * 6
ess(13,713,'Figure 13–67 scaling adder (Rf = 10 kΩ): VIN1 = +2 V with 10 kΩ, VIN2 = +3 V with 33 kΩ, VIN3 = +3 V with 91 kΩ, VIN4 = +6 V with 180 kΩ. Find VOUT and the current through Rf.','Hình 13–67 mạch cộng có trọng số (Rf = 10 kΩ): VIN1 = +2 V qua 10 kΩ, VIN2 = +3 V qua 33 kΩ, VIN3 = +3 V qua 91 kΩ, VIN4 = +6 V qua 180 kΩ. Tìm VOUT và dòng qua Rf.',
    f'VOUT = −Rf(V1/R1 + V2/R2 + V3/R3 + V4/R4) = −(2 + {10/33*3:.3f} + {10/91*3:.3f} + {10/180*6:.3f}) = −{v13:.3f} V; If = {v13/10*1e3:.1f} μA·10³ → {v13/10e3*1e6:.0f} μA.',f'VOUT = −Rf(V1/R1 + V2/R2 + V3/R3 + V4/R4) = −(2 + {10/33*3:.3f} + {10/91*3:.3f} + {10/180*6:.3f}) = −{v13:.3f} V; If = {v13/10e3*1e6:.0f} μA.','sum',3)
M.items[-1]['sol'] = B(f'VOUT = −Rf(V1/R1 + V2/R2 + V3/R3 + V4/R4) = −(2 + {10/33*3:.3f} + {10/91*3:.3f} + {10/180*6:.3f}) = −{v13:.3f} V; If = |VOUT|/Rf = {v13/10e3*1e6:.0f} μA.', f'VOUT = −Rf(V1/R1 + V2/R2 + V3/R3 + V4/R4) = −(2 + {10/33*3:.3f} + {10/91*3:.3f} + {10/180*6:.3f}) = −{v13:.3f} V; If = |VOUT|/Rf = {v13/10e3*1e6:.0f} μA.')
ess(14,713,'Input resistors of a six-input scaling adder: lowest weight 1, each next weight twice the previous, Rf = 100 kΩ.','Điện trở vào của mạch cộng 6 ngõ có trọng số: trọng số thấp nhất là 1, mỗi ngõ kế tiếp gấp đôi, Rf = 100 kΩ.',
    'Weights 1, 2, 4, 8, 16, 32 → Ri = Rf/weight = 100 kΩ, 50 kΩ, 25 kΩ, 12.5 kΩ, 6.25 kΩ, 3.125 kΩ.','Trọng số 1, 2, 4, 8, 16, 32 → Ri = Rf/trọng số = 100 kΩ, 50 kΩ, 25 kΩ, 12,5 kΩ, 6,25 kΩ, 3,125 kΩ.','sum')
sl15 = 5 / (56e3 * 0.022e-6)
ess(15,714,'Figure 13–68: step input 5 V, R = 56 kΩ, C = 0.022 μF. Rate of change of the output?','Hình 13–68: bước nhảy vào 5 V, R = 56 kΩ, C = 0.022 μF. Tốc độ biến thiên của ngõ ra là bao nhiêu?',
    f'ΔVout/Δt = −Vin/(R·C) = −5 / (56 kΩ × 0.022 μF) = −5 / {56e3*0.022e-6*1e3:.3f} ms = −{sl15:.0f} V/s = −{sl15/1e3:.2f} V/ms.',f'ΔVout/Δt = −Vin/(R·C) = −5 / (56 kΩ × 0,022 μF) = −5 / {56e3*0.022e-6*1e3:.3f} ms = −{sl15:.0f} V/s = −{sl15/1e3:.2f} V/ms.','intg')
rc18 = 15e3 * 0.047e-6; sl18 = 2 / 0.5e-3
ess(18,714,'Figure 13–70(a) differentiator (C = 0.047 μF, Rf = 15 kΩ). A triangle of 2 V peak-to-peak and period 1 ms is applied. What is the output?','Hình 13–70(a) mạch vi phân (C = 0,047 μF, Rf = 15 kΩ). Đặt sóng tam giác 2 V đỉnh–đỉnh, chu kỳ 1 ms. Ngõ ra là gì?',
    f'Slope = 2 V / 0.5 ms = {sl18:.0f} V/s. |Vout| = Rf·C·slope = {rc18*1e3:.3f} ms × {sl18:.0f} V/s = {rc18*sl18:.2f} V. Output: square wave of ±{rc18*sl18:.2f} V ({2*rc18*sl18:.2f} V p-p), inverted relative to the slope (negative while the input rises).',f'Độ dốc = 2 V / 0,5 ms = {sl18:.0f} V/s. |Vout| = Rf·C·độ dốc = {rc18*1e3:.3f} ms × {sl18:.0f} V/s = {rc18*sl18:.2f} V. Ngõ ra: sóng vuông ±{rc18*sl18:.2f} V ({2*rc18*sl18:.2f} V đỉnh–đỉnh), đảo dấu so với độ dốc (âm khi vào đang tăng).','dif',2)
sl19 = 5 / (10e3 * 10e-6)
ess(19,714,'Figure 13–70(b) integrator (R = 10 kΩ, C = 10 μF), saturation ±12 V. The switch is in position 2 (+5 V) for 10 ms, then in position 1 (−5 V) for 10 ms, repeating; Vout starts at 0 V. Describe the output.','Hình 13–70(b) mạch tích phân (R = 10 kΩ, C = 10 μF), bão hòa ±12 V. Công tắc ở vị trí 2 (+5 V) trong 10 ms rồi vị trí 1 (−5 V) trong 10 ms, lặp lại; Vout ban đầu 0 V. Mô tả ngõ ra.',
    f'Rate = ∓5/(R·C) = ∓5/0.1 s = ∓{sl19:.0f} V/s. During +5 V (10 ms): Vout falls linearly to −{sl19*0.01:.1f} V; during −5 V (10 ms): it rises back to 0 V. Triangle wave between 0 and −{sl19*0.01:.1f} V, never near saturation (±12 V).',f'Tốc độ = ∓5/(R·C) = ∓5/0,1 s = ∓{sl19:.0f} V/s. Khi vào +5 V (10 ms): Vout giảm tuyến tính đến −{sl19*0.01:.1f} V; khi vào −5 V (10 ms): tăng trở lại 0 V. Sóng tam giác giữa 0 và −{sl19*0.01:.1f} V, không chạm bão hòa (±12 V).','intg',3)
